/* Pet adoption/care/task pages use existing artwork and shared feedback. */
(() => {
 const UI=PrototypeUI,Pet=PrototypePet,q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],n=Number(location.pathname.match(/m07-p(\d+)/)?.[1]),screen=q('.screen');
 if(UI.collectionGuard(screen,'dujia-prototype-pet'))return;
 screen.dataset.petPage=String(n);
 const text=(s,v)=>{const e=q(s);if(e)e.textContent=v;},go=page=>UI.go('m07-p'+String(page).padStart(2,'0')+'.html');
 const bind=(s,fn)=>{const e=q(s);if(e){e.removeAttribute('onclick');e.onclick=fn;}};
 const button=(label,fn,cls='pet-top-action')=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.className=cls;b.onclick=fn;screen.append(b);return b;};
 function names(pet){if(!pet)return;window.PrototypePetNames.paint({pet:pet.name,actor:Pet.actor(),peer:Pet.peer()});}
 function topBack(fallback=3){if(!q('.back'))button('返回',()=>UI.back('m07-p'+String(fallback).padStart(2,'0')+'.html'),'pet-back');else bind('.back',()=>UI.back('m07-p'+String(fallback).padStart(2,'0')+'.html'));}
 const completedAdoption=()=>[2,4].includes(n)&&['pending','active'].includes(Pet.read()?.status);
 let leavingCompletedAdoption=false;
 const leaveCompletedAdoption=()=>{leavingCompletedAdoption=true;return UI.go('m03-p02.html',{replace:true,force:true});};
 function missing(){if(completedAdoption()&&performance.getEntriesByType('navigation')[0]?.type==='back_forward'){leaveCompletedAdoption();return;}UI.go(Pet.route(Pet.read()),{replace:true,force:true});}
 addEventListener('pageshow',event=>{if(event.persisted&&completedAdoption())leaveCompletedAdoption();});
 const guide=()=>UI.modal({title:'一起照顾小伙伴',message:'另一半确认领养后开始照顾。每天可互动两次，喂食补充饱食与精力。添水、互动、喂食和记录心情可完成任务；奖励只领取一次。未登录另一半的操作通过本地评审演示，不会发送真实通知。',confirm:'知道了',cancel:'关闭'});
 function note(){const form=document.createElement('form'),field=UI.components.field({label:'今天的小心情',multiline:true,maxLength:500}),input=field.input,save=UI.components.button('保存小心情');save.type='submit';form.append(field.root,save);form.className='pet-note-form';form.noValidate=true;const protect=UI.protectSheet(form);form.onsubmit=e=>{e.preventDefault();if(!UI.fieldError(input,input.value.trim()?'':'请填写今天的小心情'))return;UI.busy(save,'保存中…',async()=>{if(!Pet.note(input.value))return false;protect.commit();await UI.back();UI.toast('小心情已记录','success');paintTasks();return true;});};UI.sheet({title:'宠物小心情',message:'保存在宠物成长记录中，仅在当前浏览器演示。',content:form,actions:[],beforeClose:protect.beforeClose});}
 let tab=0,refresh=null;
 function paintTasks(){const pet=Pet.read();if(!pet)return;all('.tabs button').forEach((b,i)=>b.setAttribute('aria-selected',String(i===tab)));const daily=q('.pet-task-list');daily.hidden=tab===1;q('.pet-weekly-panel').hidden=tab===0;daily.replaceChildren();for(const task of Pet.tasks){const state=Pet.taskState(pet,task.type),row=document.createElement('div'),title=document.createElement('strong'),info=document.createElement('p'),b=document.createElement('button');row.className='pet-task-row';title.textContent=task.name;info.textContent='奖励：'+task.reward;b.type='button';if(state.claimed){b.textContent=task.type==='feed'?'喂食奖励已领取':'奖励已领取';b.disabled=true;}else if(state.done){b.textContent='领取'+({water:'添水',play:'互动',feed:'喂食',room:'小屋',note:'心情'}[task.type])+'奖励';b.onclick=()=>UI.busy(b,'领取中…',async()=>{const result=Pet.claim(task.type);if(result)return UI.go('m07-p10.html?id='+encodeURIComponent(result.id));return false;});}else{b.textContent=task.name;b.onclick=task.type==='water'?()=>UI.busy(b,'添水中…',async()=>{if(!Pet.water())return false;UI.toast('清水已添好','success');paintTasks();return true;}):task.type==='play'?()=>go(6):task.type==='feed'?()=>go(8):task.type==='room'?()=>go(15):note;}row.append(title,info,b);daily.append(row);}const count=Pet.weekCount(pet),claimed=pet.claims.includes(Pet.week()+':weekly');q('.pet-week-count').textContent=count+' / 3 次照顾';q('.pet-week-reward').textContent=pet.owned.includes('小花围巾')?'奖励：星星 ×5（围巾已拥有）':'奖励：小花围巾 ×1';const claim=q('.pet-week-claim');claim.disabled=claimed||count<3;claim.textContent=claimed?'本周奖励已领取':count>=3?'领取本周奖励':'再完成 '+(3-count)+' 次照顾';}
 function render(){const pet=Pet.read();if(![1,2,4].includes(n)&&pet?.status!=='active'){missing();return;}names(pet);
  if(n===4){if(pet&&pet.status!=='rejected'){missing();return;}topBack(3);bind('.pet-back',()=>UI.back('m03-p01.html'));bind('.adopt',()=>{if(pet?.status==='rejected'){const old=pet;UI.modal({title:'重新发起领养？',message:'另一半没有同意上次邀请。可以重新选择品种和名字。',confirm:'重新选择',cancel:'取消'}).then(ok=>{if(ok){if(UI.failNext('pet-adopt')){UI.toast('操作失败，请重试','error');return;}if(UI.write(Pet.key,null))go(2);}});}else go(2);});text('.adopt','一起领养');text('.subtitle','一起选择陪伴你们的小伙伴');bind('.guide',guide);bind('.help',guide);bind('.diary',()=>UI.modal({title:'从第一天开始记录',message:'完成共同领养后，可在任务中记录宠物小心情。',confirm:'去领养',cancel:'先看看'}).then(ok=>ok&&q('.adopt').click()));return;}
  if(n===2){if(pet){missing();return;}topBack(4);const legacy=UI.read('dujia-pet',{});let kind=['小狗','小猫','小兔','小狐狸'].includes(legacy?.kind)?legacy.kind:'小狗';all('.pet').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===kind)));all('.pet').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;all('.pet').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));});const input=q('#pet-name');if(legacy?.name)input.value=String(legacy.name).slice(0,12);text('.c1',Pet.actor());text('.c2',Pet.peer());const guard=UI.guard(screen,{fallback:'m07-p04.html',value:()=>JSON.stringify([kind,input.value])});const validate=()=>UI.fieldError(input,!input.value.trim()?'请为小伙伴取个名字':input.value.trim().length>12?'名字最多12个字':'');input.onblur=validate;input.oninput=()=>UI.fieldError(input,'');bind('#invite',()=>{if(!validate()){input.focus();return;}if(!UI.read('dujia-prototype-relationship',{})?.bound){UI.modal({title:'先关联另一半',message:'共同领养需要双方确认。请先完成关系关联。',confirm:'去关联',cancel:'继续选择'}).then(ok=>ok&&UI.go('m02-p01.html'));return;}UI.busy(q('#invite'),'邀请保存中…',async()=>{if(!Pet.adopt(kind,input.value.trim()))return false;guard.commit();return go(1);});});return;}
  if(n===1){if(!pet||pet.status!=='pending'){missing();return;}topBack(4);const leaveWaiting=()=>UI.go('m03-p02.html',{replace:true});bind('.back',leaveWaiting);bind('.pet-back',leaveWaiting);text('.card.agreed',pet.requestedBy+' 已同意领养');text('.card.waiting','等待 '+Pet.peer()+' 确认（本地邀请）');text('.hint','另一半确认后，一起照顾'+pet.name);bind('#remind',()=>UI.busy(q('#remind'),'记录提醒中…',async()=>{const latest=Pet.read();if(latest?.status!=='pending'){missing();return false;}if(latest.lastReminder&&Date.now()-latest.lastReminder<60000)throw new Error('刚刚记录过提醒，请稍后再试');latest.lastReminder=Date.now();if(!Pet.commit(latest,'pet-remind'))return false;UI.toast('已记录本地提醒；不会发送真实消息','success');return true;}));bind('.return',leaveWaiting);return;}
  topBack(3);
  if(n===3){bind('.pet-back',()=>UI.back('m03-p01.html'));text('.subtitle',pet.kind+' · 第 '+Pet.days(pet)+' 天 · 共同照顾的小伙伴');text('.house-name',pet.name+'的小屋 ♡');all('.stats strong').forEach((e,i)=>e.textContent=[pet.mood>=70?'很开心':pet.mood>=40?'很平静':'想被陪伴',pet.energy,pet.satiety,pet.affinity][i]);const latest=Pet.todayLogs(pet).find(v=>v.type!=='reward'),previous=Pet.todayLogs(pet).find(v=>v.id!==latest?.id&&v.type!=='reward');text('.care-left',latest?latest.actor+'：'+latest.text:'今天还没有照顾记录');text('.care-right',previous?previous.actor+'：'+previous.text:'从互动或喂食开始吧');text('.unlock','本周已照顾 '+Pet.weekCount(pet)+' 次，满3次领取围巾');text('.progress',Math.min(3,Pet.weekCount(pet))+'/3');all('.actions button').forEach((b,i)=>{b.removeAttribute('onclick');b.onclick=()=>go([6,8,11,12][i]);});all('.links button').forEach((b,i)=>{b.removeAttribute('onclick');b.onclick=()=>go([15,18,21][i]);});text('.go','去任务 ›');bind('.go',()=>go(11));button('宠物设置',()=>go(25));if(!pet.care||!UI.read('dujia-prototype-relationship',{})?.bound){text('.care-title','共同照顾已暂停');text('.care-left','宠物与记录已保留');text('.care-right','重新关联后可恢复照顾');}return;}
  if(n===6){let selected=0;const paint=()=>{const current=Pet.read();text('#energy',current.energy);text('.limit','今天还可以互动 '+Math.max(0,2-Pet.plays(current))+' 次');all('.stats strong').forEach((e,i)=>e.textContent=[current.energy,current.mood,current.affinity][i]);all('.option small').forEach((e,i)=>{const item=Pet.interactions[i];e.textContent=i===3?'礼物 '+current.gifts+' 份 · 消耗1份':'精力 -'+item.energy+' · 亲密 +'+item.affinity+' · 心情 +'+item.mood;});q('#play').disabled=Pet.plays(current)>=2;};all('.option').forEach((b,i)=>b.onclick=()=>{selected=i;all('.option').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));});bind('#play',()=>UI.busy(q('#play'),'陪伴中…',async()=>{const result=Pet.interact(selected);if(result?.low)return UI.go('m07-p07.html?cost='+Pet.interactions[selected].energy);if(result?.id)return UI.go('m07-p05.html?id='+encodeURIComponent(result.id));return false;}));refresh=paint;paint();return;}
  if(n===5){const id=new URLSearchParams(location.search).get('id')||pet.lastInteraction,result=pet.logs.find(v=>v.id===id&&v.type==='play');if(!result){go(6);return;}text('.title',pet.name+'很喜欢'+result.text);for(const[s,key]of [['.gain.one strong','affinity'],['.gain.two strong','mood'],['.gain.three strong','energy']])text(s,(result.delta[key]>=0?'+':'')+result.delta[key]);text('.record.first',result.actor+' 和'+pet.name+' '+result.text);text('.record.second','已保存在共同成长记录中');text('.piece','本周照顾 '+Pet.weekCount(pet)+' / 3 次');bind('.again',()=>go(6));bind('.home',()=>go(3));return;}
  if(n===7){text('.pet-info',pet.kind+' · 领养第 '+Pet.days(pet)+' 天');text('.energy span',pet.energy+'/100');text('.hint','喂食可补充精力，不会惩罚或伤害宠物');const cost=Number(new URLSearchParams(location.search).get('cost'))||5;if(pet.energy>=cost){go(6);return;}bind('.feed',()=>go(8));bind('.diary',()=>go(18));return;}
  if(n===8){let selected=0;const paint=()=>{const current=Pet.read();current.food.forEach((v,i)=>{text('#stock'+i,v);text('[data-index="'+i+'"] small','×'+v);});text('#satiety',current.satiety);q('.stock span:first-child').firstChild.textContent='主粮';text('.foods button:first-child strong','香香主粮');all('.foods em').forEach((e,i)=>e.textContent='饱食+'+Pet.foods[i].satiety+' 精力+'+Pet.foods[i].energy+(Pet.foods[i].mood?' 心情+'+Pet.foods[i].mood:''));const latest=Pet.todayLogs(current).find(v=>v.type==='feed');text('.shared',latest?latest.actor+' 今天已经喂过食，仍可继续照顾':'今天还没有喂食记录');text('.time',latest?latest.text:'选择食物，喂食后同步保存');};all('.foods button').forEach((b,i)=>b.onclick=()=>{selected=i;all('.foods button').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));});bind('#feed',()=>UI.busy(q('#feed'),'喂食中…',async()=>{const result=Pet.feed(selected);if(result?.empty)return UI.go('m07-p09.html?food='+selected);if(result?.saved){paint();UI.toast('喂食已记录，精力和饱食已更新','success');return true;}return false;}));bind('.more',()=>go(11));refresh=paint;paint();return;}
  if(n===9){q('.back').lastChild.textContent='返回';const requested=new URLSearchParams(location.search).get('food'),index=requested!==null?Number(requested):pet.food.findIndex(v=>v===0),total=pet.food.reduce((sum,v)=>sum+v,0);if(total>0&&(!Number.isInteger(index)||index<0||index>2||pet.food[index]>0)){go(8);return;}text('.today strong',total);text('.empty',total===0?'食物用完啦':Pet.foods[index]?.name+'用完啦');text('.task-copy',total?'可以换一种食物，或做任务领取主粮':'完成添水任务可领取主粮和礼物');bind('.task',()=>go(11));if(total)button('换一种食物',()=>go(8));return;}
  if(n===10){const id=new URLSearchParams(location.search).get('id')||pet.lastReward,result=pet.logs.find(v=>v.id===id&&v.type==='reward');if(!result){go(11);return;}text('.subtitle','奖励来自已完成的共同照顾任务');text('.reward',result.text);text('.wardrobe','已保存到宠物库存');text('.event.e1',result.actor+' 领取了奖励');text('.event.e2',result.date+' · 同一任务只领取一次');text('.synced','当前浏览器中的共同数据已更新');text('.wear','返回任务');bind('.wear',()=>go(11));return;}
  if(n===11){text('.next','返回小屋');bind('.next',()=>go(3));for(const e of all('.task,.task-button,.weekly,.count,.reward'))e.hidden=true;const daily=document.createElement('section');daily.className='pet-task-list';daily.setAttribute('aria-label','每日任务');const weekly=document.createElement('section');weekly.className='pet-weekly-panel';const title=document.createElement('h2');title.textContent='本周一起照顾3次';const count=document.createElement('p');count.className='pet-week-count';const reward=document.createElement('p');reward.className='pet-week-reward';reward.textContent='奖励：小花围巾 ×1';const b=document.createElement('button');b.className='pet-week-claim';b.onclick=()=>UI.busy(b,'领取中…',async()=>{const result=Pet.claim('weekly');if(result)return UI.go('m07-p10.html?id='+encodeURIComponent(result.id));return false;});weekly.append(title,count,reward,b);screen.append(daily,weekly);all('.tabs button').forEach((b,i)=>b.onclick=()=>{tab=i;paintTasks();});paintTasks();}
 }
 const load=async()=>{screen.setAttribute('aria-busy','true');let status=q('.pet-load');if(!status){status=document.createElement('section');status.className='pet-load';status.setAttribute('role','status');screen.append(status);}status.replaceChildren();status.append(UI.components.loading({mode:'skeleton',label:'正在读取小伙伴的记录…'}));await new Promise(resolve=>setTimeout(resolve,400));screen.setAttribute('aria-busy','false');try{if(UI.failNext('pet-load'))throw new Error('宠物记录加载失败');Pet.confirmation();status.remove();render();}catch(error){status.replaceChildren(UI.components.state({kind:'error',title:error.message,action:'重新加载',onAction:load}));}};
 addEventListener('storage',event=>{if(leavingCompletedAdoption)return;if(![Pet.key,'dujia-prototype-relationship'].includes(event.key))return;if(n===2||document.querySelector('dialog[open]')){UI.toast('共同数据已更新，当前输入保留；请核对后继续');return;}if(refresh&&Pet.read()?.status==='active'){refresh();return;}location.reload();});load();
})();
